#include "ksPanelInitializeTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PanelInitializeTask;using S=T::Stage;using K=T::Kind;using C=T::Child;using W=T::Write;unsigned cases=0;for(unsigned kind=0;kind<3;++kind)for(unsigned split=0;split<256;++split){T t(static_cast<K>(kind));unsigned used=0,children=0;std::vector<std::pair<W,unsigned>>writes;while(t.stage()!=S::Complete){if(t.child()!=C::None){if(t.child()!=(kind==1?C::Wake:C::Control)||t.index()!=(kind==2?children:0))throw std::runtime_error("child order");++children;t.resumeChild();continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](W,uint8_t){throw std::runtime_error("early write");}))throw std::runtime_error("early budget");used+=t.advanceBefore(split<cost?cost:split,[&](W w,uint8_t v){writes.emplace_back(w,v);});}std::vector<std::pair<W,unsigned>>expected=kind==1?std::vector<std::pair<W,unsigned>>{{W::Holdoff,0x19}}:kind==2?std::vector<std::pair<W,unsigned>>{{W::DecayMask,0},{W::DecayInvert,0},{W::Holdoff,0},{W::PendingMask,0},{W::PendingInvert,0},{W::Invert,0},{W::Mask,255}}:std::vector<std::pair<W,unsigned>>{};if(writes!=expected||used!=(kind==0?17:kind==1?77:717)||children!=(kind==0?0:kind==1?1:20)||t.index()!=(kind==2?20:0)||t.remaining()||t.resumeChild())throw std::runtime_error("initialize state/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-initialize properties\n";}
